# search returns a dict, let's check its type
import asyncio

for term in ["[grade]", "[grader tail]", "[facts]", "[first wrong step]"]:
    results = await CONTEXT.search(term)
    print(f"\n=== {term} ===")
    print(f"type: {type(results)}")
    if isinstance(results, dict):
        for k, v in results.items():
            print(f"  {k}: {str(v)[:300]}")
    elif isinstance(results, list):
        for i, r in enumerate(results[:5]):
            print(f"  [{i}]: {str(r)[:300]}")
    else:
        print(f"  {str(results)[:500]}")
